import test from 'node:test';
import assert from 'node:assert/strict';
import { gunzipSync } from 'node:zlib';
import { assertObservedNativeRuntime as assertProductionObservation } from '../programmable/lib/native-runtime-observer.mjs';

// Recorded public runtime/ABI bytes from the September 8 evidence capture. RPC envelopes,
// checkpoint and the Universal Router source-service response below are synthetic fixtures.
// They establish no live source match or provider admission. The latter intentionally models
// a future source match; the actual recorded Universal Router endpoint returned 404.
const FIXTURE = JSON.parse(gunzipSync(Buffer.from('', 'base64')));
let observeNativeRuntimeAuthority, assertObservedNativeRuntime;
let moduleId = 0;
const BLOCK = { number: '0x64', hash: `0x${'ab'.repeat(32)}`, timestamp: '0x100' };
const safeNames = ['safeSingletonSlot', 'safeFallbackHandlerSlot', 'safeGuardSlot', 'safeOwners', 'safeThreshold', 'safeNonce', 'safeModules', 'safeVersion'];
async function withFetch(t, change = () => {}) {
  const original = globalThis.fetch;
  const calls = []; let safeIndex = 0; let blockIndex = 0;
  globalThis.fetch = async (url, options) => {
    assert.equal(options.redirect, 'error');
    assert.ok(options.signal instanceof AbortSignal);
    const request = options.body ? JSON.parse(options.body) : null;
    calls.push({ url, request });
    let value, raw, status = 200;
    if (request) {
      let result;
      if (request.method === 'eth_chainId') result = '0x1237';
      else if (request.method === 'eth_getBlockByNumber') {
        if (request.params[0] === '0x0') result = { hash: FIXTURE.capabilities.chainDeployment.permit2GenesisProvenance.genesisBlockHash ?? '0xaad15f3d702aaea00caf3e9bb56395efe9127bc3b31b24921abf1eee3409305c' };
        else { result = { ...BLOCK }; blockIndex++; }
      } else {
        assert.deepEqual(request.params.at(-1), { blockHash: BLOCK.hash, requireCanonical: true });
        if (request.method === 'eth_getCode') result = FIXTURE.codes[request.params[0].toLowerCase()];
        else result = FIXTURE.safeReads[safeNames[safeIndex++]];
      }
      assert.notEqual(result, undefined, 'fixture must explicitly model every RPC');
      value = { jsonrpc: '2.0', id: request.id, result };
    } else if (url.includes('/capabilities')) value = structuredClone(FIXTURE.capabilities);
    else if (url.endsWith('/SafeProxy.json')) raw = FIXTURE.proxyRaw;
    else if (url.endsWith('/safe.json')) raw = FIXTURE.safeRaw;
    else if (url.endsWith('/compatibility_fallback_handler.json')) raw = FIXTURE.fallbackRaw;
    else {
      const address = new URL(url).pathname.split('/').at(-1).toLowerCase();
      value = structuredClone(FIXTURE.sources[address] ?? {
        chainId: '4663', address, match: 'match', runtimeMatch: 'match', proxyResolution: { isProxy: false },
        runtimeBytecode: { onchainBytecode: FIXTURE.codes[address] },
        abi: [{ type: 'function', name: 'syntheticAbiOnly', inputs: [], outputs: [], stateMutability: 'view' }],
      });
    }
    const response = { url, request, value, raw, status, blockIndex };
    await change(response);
    return new Response(response.raw ?? JSON.stringify(response.value), { status: response.status, headers: { 'Content-Type': 'application/json' } });
  };
  t.after(() => { globalThis.fetch = original; });
  // Isolated synthetic namespace cannot confer the production module's private brand.
  ({ observeNativeRuntimeAuthority, assertObservedNativeRuntime } = await import(`../programmable/lib/native-runtime-observer.mjs?synthetic=${++moduleId}`));
  return calls;
}

test('synthetic complete observation binds nine runtimes and the complete unchanged evidence closure', async t => {
  const calls = await withFetch(t);
  const observed = await observeNativeRuntimeAuthority();
  assert.equal(assertObservedNativeRuntime(observed), observed);
  assert.throws(() => assertProductionObservation(observed), /UNOBSERVED_RUNTIME/);
  assert.equal(observed.runtime.contracts.length, 9);
  assert.deepEqual(observed.runtime.contracts.map(x => x.role), observed.runtime.contracts.map(x => x.role).sort());
  assert.deepEqual(observed.runtime.evidenceFiles.map(x => x.path), Object.keys(observed.evidenceBytes).sort());
  for (const contract of observed.runtime.contracts) {
    assert.ok(Buffer.isBuffer(observed.evidenceBytes[contract.codePath]));
    assert.ok(JSON.parse(observed.evidenceBytes[contract.abiPath]).length > 0);
    assert.equal(contract.blockHash, BLOCK.hash);
  }
  assert.equal(calls.filter(x => x.request?.method === 'eth_getCode').length, 11);
  assert.throws(() => assertObservedNativeRuntime(structuredClone(observed)), /UNOBSERVED_RUNTIME/);
  const code = observed.evidenceBytes[observed.runtime.contracts[0].codePath];
  code[0] ^= 1;
  assert.throws(() => assertObservedNativeRuntime(observed), /OBSERVATION_CHANGED/);
});

for (const [name, change, error] of [
  ['wrong chain', r => { if (r.request?.method === 'eth_chainId') r.value.result = '0x1'; }, /CHAIN_MISMATCH/],
  ['wrong genesis', r => { if (r.request?.params?.[0] === '0x0') r.value.result.hash = `0x${'00'.repeat(32)}`; }, /GENESIS_MISMATCH/],
  ['missing finalized checkpoint', r => { if (r.request?.params?.[0] === 'finalized') r.value.result = null; }, /UNFINALIZED_CHECKPOINT/],
  ['changed canonical checkpoint', r => { if (r.request?.method === 'eth_getBlockByNumber' && r.request.params[0] === BLOCK.number) r.value.result.hash = `0x${'cd'.repeat(32)}`; }, /CHECKPOINT_CHANGED/],
  ['regressed finality', r => { if (r.request?.params?.[0] === 'finalized' && r.blockIndex > 1) r.value.result.number = '0x63'; }, /UNFINALIZED_CHECKPOINT/],
  ['wrong runtime bytes', r => { if (r.request?.method === 'eth_getCode') r.value.result = '0x6000'; }, /RUNTIME_MISMATCH/],
  ['missing ABI', r => { if (r.url.includes('sourcify')) r.value.abi = []; }, /ABI_CORRESPONDENCE_UNAVAILABLE/],
  ['unmatched ABI runtime', r => { if (r.url.includes('sourcify')) r.value.runtimeBytecode.onchainBytecode = '0x6000'; }, /ABI_RUNTIME_MISMATCH/],
  ['unverified source', r => { if (r.url.includes('sourcify')) r.value.runtimeMatch = null; }, /ABI_CORRESPONDENCE_UNAVAILABLE/],
  ['unavailable Universal Router correspondence', r => { if (r.url.includes('sourcify') && r.url.includes('06afba43')) { r.status = 404; r.value = { error: 'not found' }; } }, /ABI_CORRESPONDENCE_UNAVAILABLE/],
  ['Safe singleton drift', r => { if (r.request?.method === 'eth_getStorageAt') r.value.result = `0x${'00'.repeat(32)}`; }, /SAFE_POLICY_DRIFT/],
  ['Safe owners drift', r => { if (r.request?.method === 'eth_call' && r.request.params[0].data === '0xa0e67e2b') r.value.result = '0x'; }, /SAFE_POLICY_DRIFT/],
  ['published policy drift', r => { if (r.url.includes('capabilities')) r.value.chainDeployment.permitAuthoritySourceProvenance.configurationEvidence.threshold = 2; }, /SAFE_POLICY_DRIFT/],
  ['RPC historical unsupported', r => { if (r.request?.method === 'eth_getCode') { delete r.value.result; r.value.error = { code: -32000, message: 'metadata is not found' }; } }, /RPC_READ_FAILED/],
  ['provider role drift', r => { if (r.url.includes('capabilities')) r.value.chainDeployment.contracts.poolManager.runtimeCodeHash = `0x${'00'.repeat(32)}`; }, /DESCRIPTOR_DRIFT/],
]) test(`observer refuses ${name}`, async t => {
  const calls = await withFetch(t, change);
  await assert.rejects(observeNativeRuntimeAuthority(), error);
  assert.ok(calls.every(x => !x.request || !x.request.params.includes('latest')), 'no latest fallback');
});

test('observer rejects credential-bearing or insecure RPC URLs before fetching', async t => {
  let fetched = false; const original = globalThis.fetch;
  globalThis.fetch = async () => { fetched = true; throw new Error('unexpected network'); };
  t.after(() => { globalThis.fetch = original; });
  for (const rpcUrl of ['http://example.org', 'https://owner:secret@localhost', 'https://example.org?apiKey=secret']) await assert.rejects(observeNativeRuntimeAuthority({ rpcUrl }), /INVALID_URL/);
  assert.equal(fetched, false);
});

for (const [name, response, error] of [
  ['oversized response', () => new Response('x', { headers: { 'content-length': '2500001' } }), /RESPONSE_TOO_LARGE/],
  ['cross-origin redirect', () => ({ redirected: true, url: 'https://other.example' }), /REDIRECT_REFUSED/],
]) test(`observer refuses ${name} before creating a snapshot`, async t => {
  const original = globalThis.fetch;
  globalThis.fetch = async () => response();
  t.after(() => { globalThis.fetch = original; });
  const isolated = await import(`../programmable/lib/native-runtime-observer.mjs?bounds=${++moduleId}`);
  await assert.rejects(isolated.observeNativeRuntimeAuthority(), error);
});

test('exact source matches and nonzero Safe nonce preserve observation only', async t => {
  await withFetch(t, r => {
    if (r.url.includes('sourcify')) r.value.match = r.value.runtimeMatch = 'exact_match';
    if (r.request?.method === 'eth_call' && r.request.params[0].data === '0xaffed0e0') r.value.result = `0x${'0'.repeat(63)}7`;
    if (r.url.includes('/capabilities')) r.value.chainDeployment.permitAuthoritySourceProvenance.configurationEvidence.nonce = '7';
  });
  const result = await observeNativeRuntimeAuthority();
  assert.equal(BigInt(JSON.parse(result.evidenceBytes['responses/safeNonce.json']).result), 7n);
  assert.throws(() => assertProductionObservation(result), /UNOBSERVED_RUNTIME/);
});
test('canonical proxy artifact drift refuses before delegated Safe calls', async t => {
  const calls = await withFetch(t, r => { if (r.url.endsWith('/SafeProxy.json')) r.raw = '{}'; });
  await assert.rejects(observeNativeRuntimeAuthority(), /SAFE_PROXY_SOURCE_DRIFT/);
  assert.equal(calls.some(x => x.request?.method === 'eth_call'), false);
});
test('observer retains import-time transport after global replacement', async t => {
  await withFetch(t);
  globalThis.fetch = async () => { throw new Error('replacement must not run'); };
  const result = await observeNativeRuntimeAuthority();
  assert.equal(assertObservedNativeRuntime(result), result);
  assert.throws(() => assertProductionObservation(result), /UNOBSERVED_RUNTIME/);
});


test('captured hash checkpoint receives no capability until its finality and canonical recheck', async t => {
  let release, entered, resolved = false;
  const pending = new Promise(resolve => { release = resolve; });
  const atFinality = new Promise(resolve => { entered = resolve; });
  const calls = await withFetch(t, async response => {
    if (response.request?.params?.[0] === 'finalized') { entered(); await pending; }
  });
  const running = observeNativeRuntimeAuthority({ checkpointMode: 'capture-then-finalize' }).then(value => { resolved = true; return value; });
  await atFinality;
  assert.equal(resolved, false);
  release();
  const result = await running;
  assert.equal(assertObservedNativeRuntime(result), result);
  assert.equal(calls.filter(call => call.request?.params?.[0] === 'latest').length, 1);
  assert.equal(calls.filter(call => call.request?.method === 'eth_getCode').length, 11);
  assert.ok(result.runtime.contracts.every(contract => contract.blockHash === BLOCK.hash));
  assert.throws(() => assertProductionObservation(result), /UNOBSERVED_RUNTIME/);
});

test('captured hash checkpoint refuses a reorg even after finality advances', async t => {
  await withFetch(t, response => {
    if (response.request?.params?.[0] === 'finalized') response.value.result.number = '0x65';
    if (response.request?.method === 'eth_getBlockByNumber' && response.request.params[0] === BLOCK.number) response.value.result.hash = `0x${'cd'.repeat(32)}`;
  });
  await assert.rejects(observeNativeRuntimeAuthority({ checkpointMode: 'capture-then-finalize' }), /CHECKPOINT_CHANGED/);
});

test('unsupported capture mode refuses without network activity', async t => {
  const calls = await withFetch(t);
  await assert.rejects(observeNativeRuntimeAuthority({ checkpointMode: 'latest-only' }), /INVALID_CHECKPOINT_MODE/);
  assert.equal(calls.length, 0);
});


test('permit authority includes the verified fallback signature interface', async t => {
  await withFetch(t);
  const observed = await observeNativeRuntimeAuthority();
  const role = observed.runtime.contracts.find(contract => contract.role === 'permitAuthority');
  const combined = JSON.parse(observed.evidenceBytes[role.abiPath]);
  const details = JSON.parse(observed.evidenceBytes[role.observationPath]);
  const fallback = JSON.parse(observed.evidenceBytes[details.fallbackAbiPath]);
  assert.ok(fallback.some(item => item.type === 'function' && item.name === 'isValidSignature'));
  assert.ok(combined.some(item => item.type === 'function' && item.name === 'isValidSignature'));
  assert.equal(combined.filter(item => item.type === 'constructor').length, 1);
});
